          ),
        }}
        sx={{ minWidth: 240 }}
      />
      <UniversalFilter
        id="code-with-search"
        filters={filters}
        selectedFilters={selectedFilters}
        setSelectedFilters={setSelectedFilters}
        handleApplyFilter={(next) => console.log("Search:", search, "Filters:", next)}
        variant="outlined"
      />
    </Box>
  );
};

